<template><view class="page"><view class="card"><text class="heading">农事日历与编排</text><text class="muted">{{farmName}}</text><button class="primary" @click="newPlan">编排一周农事</button></view><view v-if="error" class="error">{{error}}<button size="mini" @click="load">重试</button></view><view v-for="row in rows" :key="row.id" class="card" @click="open(row)"><view class="row"><text>{{row.weekStart}} 起一周</text><text>{{label(row.status)}}</text></view><text class="muted">V{{row.revision}} · {{row.createdAt}}</text></view><view v-if="!loading&&!rows.length&&!error" class="card muted">暂无编排，选择计划阶段开始安排。</view>
<view v-for="item in interventions" :key="item.id" class="card"><text class="heading">技术员介入 · {{item.weekStart}}</text><business-detail :value="item"/><button v-if="item.state!=='RESOLVED'" size="mini" @click="intervention=item;interventionForm={}">登记处理</button></view><view v-if="intervention" class="card"><business-fields :fields="[note('reason','处理说明',true)]" v-model="interventionForm"/><button :disabled="busy" @click="resolveIntervention">确认处理</button></view><view v-if="detail" class="card"><text class="heading">当前编排</text><button size="mini" @click="exportSnapshot">导出当前方案</button><business-detail :value="detail"/><view class="buttons"><button size="mini" @click="editDetail">调整安排</button><button v-for="a in actions" :key="a.key" size="mini" :disabled="busy" @click="action=a.key">{{a.label}}</button></view><view v-if="action"><business-fields :fields="actionFields" v-model="actionForm"/><button class="primary" :disabled="busy" :loading="busy" @click="sendAction">确认{{actions.find(a=>a.key===action)?.label}}</button></view></view>
<view v-if="editing" class="overlay"><view class="head"><text>{{editingId?'调整编排':'新建编排'}}</text><button size="mini" :disabled="busy" @click="editing=false">关闭</button></view><scroll-view scroll-y class="body"><business-fields :fields="baseFields" v-model="form" :disabled="busy"/><button size="mini" :disabled="busy" @click="refreshWeather">刷新真实天气</button><view class="card"><text class="heading">选择计划阶段</text><checkbox-group @change="selectedStages=$event.detail.value"><label v-for="s in context?.stages || []" :key="s.stageId" class="stage"><checkbox :value="String(s.stageId)" :checked="selectedStages.includes(String(s.stageId))" color="#0f7a45"/>{{s.plotName}} · {{s.cropName}} · {{s.stageName}}</label></checkbox-group><button size="mini" @click="addStages">加入安排</button></view><view v-for="(day,index) in days" :key="day.date" class="card"><text class="heading">{{day.date}}</text><business-fields :fields="dayFields" :model-value="day" @update:model-value="days[index]=$event"/><text class="muted">{{day.note || '天气尚未核验'}}</text></view><view v-for="(op,index) in operations" :key="op.key" class="card"><text class="heading">{{op.taskName}}</text><business-fields :fields="opFields" :model-value="op" @update:model-value="operations[index]=$event"/><button v-if="detail?.status!=='PUBLISHED' || !editingId" size="mini" @click="operations.push({...op,key:uid(),taskName:op.taskName+'（新增农事）'})">同阶段新增农事</button><button v-if="detail?.status!=='PUBLISHED' || !editingId" size="mini" @click="operations.splice(index,1)">移除此项</button></view><view v-if="saveError" class="error">{{saveError}}</view><view style="height:50rpx"/></scroll-view><view class="bottom"><button class="primary" :loading="busy" :disabled="busy||!operations.length" @click="save">保存并计算安排</button></view></view></view></template>
<script setup lang="ts">
import {saveText} from '@/utils/business-files'
async function exportSnapshot(){try{if(!detail.value)throw new Error('请先选择方案');await saveText('农事编排.json',JSON.stringify(detail.value,null,2))}catch(e:any){error.value=e.message}}
import {ref,computed,watch} from 'vue'
import {onShow,onHide,onBackPress,onPullDownRefresh} from '@dcloudio/uni-app'
import {call,date,text,number,note,yesno,select,choice,statusLabels} from '@/api/native-business'
import type {Row,Field} from '@/api/native-business'
import {ensureWorkspaceSession,isProductionOps} from '@/utils/workspace'
import {resolveCurrentFarm} from '@/utils/auth-helper'
import {productionContextVersion} from '@/utils/request'
import BusinessFields from '@/components/business-fields/business-fields.vue'
import BusinessDetail from '@/components/business-detail/business-detail.vue'
const interventions=ref<Row[]>([]),intervention=ref<Row>(),interventionForm=ref<Row>({})
const rows=ref<Row[]>([]),detail=ref<Row>(),context=ref<Row>(),farmId=ref(''),farmName=ref(''),error=ref(''),saveError=ref(''),loading=ref(false),busy=ref(false),editing=ref(false),editingId=ref(''),editingRevision=ref(0),form=ref<Row>({}),days=ref<Row[]>([]),operations=ref<Row[]>([]),selectedStages=ref<string[]>([]),action=ref(''),actionForm=ref<Row>({})
let version=0,scope=0
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2)
const label=(v:string)=>statusLabels[v]||v
const baseFields=[date('weekStart','周起始日期',true),text('source','农事依据来源',true),note('reason','调整说明'),yesno('crossMonthConfirmed','技术员已确认跨月调整')]
const dayFields=[number('people','可用人数',true),number('machineSlots','机具位',true),number('greenhouseTemperature','棚内温度')]
const opFields=computed<Field[]>(()=>[text('taskName','具体农事名称',true),date('floweringStart','开花窗口开始'),date('floweringEnd','开花窗口结束'),date('earliest','最早日期',true),date('latest','最迟日期',true),number('people','所需人数',true,1),number('machineSlots','所需机具位',true),select('memberId','负责人',(context.value?.members||[]).map((m:Row)=>({value:m.id,label:m.memberName})),true),text('standardRef','作业标准依据',true),select('taskType','农事类型',choice({pruning:'整枝疏果',fertilizing:'追肥',ventilation:'通风控湿',pollination:'授粉',harvesting:'采收',pest_control:'施药防治',irrigating:'灌溉',other:'其他'}),true),number('priority','优先级',true,1),yesno('mandatory','必须完成'),yesno('greenhouse','设施大棚'),yesno('weatherSensitive','受天气影响'),text('requiredSkill','技能要求'),text('skillEvidence','技能依据'),date('harvestDate','预计采收日'),number('safetyIntervalDays','安全间隔（天）'),text('registrationRef','登记依据')])
const actions=computed(()=>[{key:'approve',label:'审核确认'},{key:'publish',label:'下发任务'},{key:'close',label:'验收结案'},{key:'explain',label:'解释安排'}])
const actionFields=[note('reason','处理说明',true),yesno('crossMonthConfirmed','已确认跨月安排')]
function dayList(start:string){return Array.from({length:7},(_,i)=>{const d=new Date(start+'T12:00:00');d.setDate(d.getDate()+i);const date=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');return {date,people:0,machineSlots:0,rain:false,strongWind:false,weatherVerified:false}})}
watch(()=>form.value.weekStart,(v,old)=>{if(v&&old&&v!==old){days.value=dayList(v);form.value.weatherSource='';form.value.weatherIssuedAt=''}})
async function load(){const token=++version;loading.value=true;error.value='';try{if(!await ensureWorkspaceSession())return;if(isProductionOps())throw new Error('请切换到用户端');const farm=await resolveCurrentFarm();if(!farm)return;farmId.value=String(farm.farmId);farmName.value=farm.farmName||'';scope=productionContextVersion();const [list,ctx,needs]=await Promise.all([call('/calendar-arrangements','GET',undefined,{farmId:farmId.value}),call('/calendar-arrangements/context','GET',undefined,{farmId:farmId.value}),call('/calendar-arrangements/interventions','GET',undefined,{farmId:farmId.value})]);if(token===version){rows.value=list;context.value=ctx;interventions.value=needs}}catch(e:any){error.value=e.message}finally{loading.value=false;uni.stopPullDownRefresh()}}
async function open(row:Row){error.value='';try{detail.value=await call('/calendar-arrangements/'+row.id);action.value='';actionForm.value={}}catch(e:any){error.value=e.message}}
function newPlan(){const now=new Date(),start=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');form.value={weekStart:start,source:''};days.value=dayList(start);operations.value=[];selectedStages.value=[];editingId.value='';editing.value=true;saveError.value=''}
function editDetail(){if(!detail.value)return;const input=detail.value.input;form.value={...input,reason:''};days.value=JSON.parse(JSON.stringify(input.days));operations.value=JSON.parse(JSON.stringify(input.operations));editingId.value=detail.value.id;editingRevision.value=detail.value.revision;editing.value=true;saveError.value=''}
function addStages(){for(const id of selectedStages.value){const s=context.value?.stages.find((x:Row)=>String(x.stageId)===id);if(!s||operations.value.some(o=>String(o.stageId)===id))continue;operations.value.push({key:uid(),planId:s.planId,stageId:s.stageId,taskName:s.cropName+' · '+s.stageName,taskType:s.taskType||'other',mandatory:true,priority:2,earliest:s.earliest||form.value.weekStart,latest:s.latest||days.value[6].date,people:1,machineSlots:0,standardRef:s.source||'',greenhouse:false,weatherSensitive:true})}}
async function refreshWeather(){if(busy.value)return;busy.value=true;saveError.value='';try{const w=await call('/calendar-arrangements/weather/refresh','POST',{farmId:farmId.value,weekStart:form.value.weekStart});form.value.weatherSource=w.provider||w.error;form.value.weatherIssuedAt=w.issuedAt;days.value=days.value.map(day=>({...day,...(w.days?.find((d:Row)=>d.date===day.date)||{weatherVerified:false,note:w.error})}));if(w.status!=='SUCCESS')saveError.value=w.error||'预报未核验'}catch(e:any){saveError.value=e.message}finally{busy.value=false}}
async function save(){if(busy.value)return;saveError.value='';try{if(scope!==productionContextVersion())throw new Error('业务范围已变更');if(!form.value.source?.trim())throw new Error('请填写农事依据来源');for(const o of operations.value){if(!o.memberId||!o.standardRef||o.earliest>o.latest)throw new Error('请补全负责人、标准依据和有效日期');for(const k of ['people','machineSlots','priority','memberId','safetyIntervalDays'])if(o[k]!==''&&o[k]!==undefined)o[k]=Number(o[k])}const input={farmId:farmId.value,requestId:uid(),weekStart:form.value.weekStart,source:form.value.source,weatherSource:form.value.weatherSource,weatherIssuedAt:form.value.weatherIssuedAt,days:days.value.map(d=>({...d,people:Number(d.people),machineSlots:Number(d.machineSlots)})),operations:operations.value};busy.value=true;const published=detail.value?.status==='PUBLISHED';detail.value=await call('/calendar-arrangements'+(editingId.value?'/'+editingId.value+(published?'/reschedule':''):''),editingId.value&&!published?'PUT':'POST',editingId.value?{revision:editingRevision.value,reason:form.value.reason,input,crossMonthConfirmed:form.value.crossMonthConfirmed===true}:input);editing.value=false;await load();uni.showToast({title:'编排已保存',icon:'success'})}catch(e:any){saveError.value=e.message}finally{busy.value=false}}
async function sendAction(){if(busy.value||!detail.value)return;error.value='';try{if(scope!==productionContextVersion())throw new Error('业务范围已变更');if(!actionForm.value.reason?.trim())throw new Error('请填写处理说明');busy.value=true;detail.value=await call('/calendar-arrangements/'+detail.value.id+'/'+action.value,'POST',{revision:detail.value.revision,...actionForm.value});action.value='';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function resolveIntervention(){if(busy.value||!intervention.value)return;try{if(scope!==productionContextVersion())throw new Error('业务范围已变化');if(!interventionForm.value.reason?.trim())throw new Error('请填写处理说明');busy.value=true;await call('/calendar-arrangements/interventions/'+intervention.value.id+'/resolve','POST',{reason:interventionForm.value.reason});intervention.value=undefined;await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
onShow(()=>void load());onPullDownRefresh(()=>void load());onHide(()=>{version++;editing.value=false;detail.value=undefined});onBackPress(()=>{if(busy.value)return true;if(editing.value){editing.value=false;return true}return false})
</script>
<style scoped>.page{padding:24rpx;background:#f4f6f2}.card{padding:26rpx;margin:0 0 24rpx;background:#fff;border-radius:18rpx}.heading{display:block;font-size:31rpx;font-weight:600;margin-bottom:18rpx}.muted{display:block;color:#666666;font-size:24rpx;margin:14rpx 0;line-height:1.6}.row,.buttons{display:flex;justify-content:space-between;gap:14rpx;flex-wrap:wrap;font-size:28rpx}.buttons button{margin:12rpx 0;min-height:76rpx;font-size:25rpx}.primary{background:#0f7a45;color:white;font-size:28rpx;margin-top:20rpx}.stage{display:flex;align-items:center;gap:12rpx;padding:20rpx 0;font-size:26rpx;line-height:1.6}.error{color:#a34229;background:#fff0e9;padding:24rpx;line-height:1.6;font-size:26rpx;margin:20rpx 0}.overlay{position:fixed;inset:0;top:var(--window-top,0px);z-index:90;background:#fff;display:flex;flex-direction:column}.head{padding:24rpx;display:flex;align-items:center;justify-content:space-between;font-size:30rpx}.head button{margin:0}.body{height:0;flex:1;box-sizing:border-box;padding:0 28rpx}.bottom{padding:20rpx 28rpx calc(20rpx + env(safe-area-inset-bottom))}</style>
